_editor_class["sc_1_p4_la1"]=Class(laser)
_editor_class["sc_1_p4_la1"].init=function(self,_x,_y,angle)
    laser.init(self,COLOR_RED,_x,_y,0,1,500,1,8,5,10)
    laser.ChangeImage(self,4)
    self.bound=false
    self.is_contact=0
    lasttask=task.New(self,function()
        SetV2(self,0,angle,true,false)
        self.colli=false
        
        laser._TurnOn(self,10,true,true)
        self.colli=true
        for _=1,_infinite do
            local l1 = self.l1
            local l2 = self.l2
            local l3 = self.l3
            local angle1 = angle % 360
            local r1 = 80
            
            -- 激光方向向量
            local dir_x = cos(angle1)
            local dir_y = sin(angle1)
            
            -- 玩家相对发射源的向量
            local dx = player.x - self.x
            local dy = player.y - self.y
            local dist_player_sq = dx^2 + dy^2
            
            -- 射线方程：P = self + t * dir，求与玩家判定圆的交点
            -- |P - player|^2 = r1^2
            -- 展开成关于t的二次方程：at^2 + bt + c = 0
            local a = dir_x^2 + dir_y^2  -- 实际上 = 1
            local b = 2 * (self.x * dir_x - player.x * dir_x + self.y * dir_y - player.y * dir_y)
            local c = dist_player_sq - r1^2
            
            -- 判别式
            local discriminant = b^2 - 4*a*c
            
            if discriminant >= 0 and c < 0 then
                -- 有交点，且发射源在圆内或圆边缘（c<0表示发射源到玩家距离<r1，或者刚好等于）
                -- 取较小的t（最近的交点）
                local t = (-b - sqrt(discriminant)) / (2*a)
                
                if t > 0 then
                    -- 交点在激光前方
                    self.head_x = self.x + t * dir_x
                    self.head_y = self.y + t * dir_y
                    self.l2 = t - l1 - l3
                    self.is_contact = 1
                else
                    self.l2 = 500
                    self.is_contact = 0
                end
            elseif discriminant >= 0 then
                -- 有交点，发射源在圆外
                local t = (-b - sqrt(discriminant)) / (2*a)
                
                if t > 0 then
                    -- 检查玩家是否在激光圆柱体判定内
                    local proj = dx * dir_x + dy * dir_y  -- 玩家在激光方向上的投影
                    if proj > 0 then
                        local perp_dist_sq = dist_player_sq - proj^2  -- 垂直距离的平方
                        if perp_dist_sq <= r1^2 then
                            -- 在圆柱体内
                            self.head_x = self.x + t * dir_x
                            self.head_y = self.y + t * dir_y
                            self.l2 = t - l1 - l3
                            self.is_contact = 1
                        else
                            self.l2 = 500
                            self.is_contact = 0
                        end
                    else
                        self.l2 = 500
                        self.is_contact = 0
                    end
                else
                    self.l2 = 500
                    self.is_contact = 0
                end
            else
                -- 无交点
                self.l2 = 500
                self.is_contact = 0
            end
            
            task._Wait(1)
        end
    end)
    lasttask=task.New(self,function()
        for _=1,_infinite do
            _set_rel_pos(self,0,0,self.rot,false)
            task._Wait(1)
        end
    end)
    lasttask=task.New(self,function()
        task._Wait(10)
        for _=1,_infinite do
            if self.is_contact==1 then
                PlaySound("tan02",0.1,self.x/256,false)
                last=New(_straight,arrow_big,COLOR_ORANGE,self.head_x,self.head_y,1,0,true,0,true,true,180,false,0,0,0,false)
                last=New(_straight,arrow_big,COLOR_RED,self.head_x,self.head_y,1.5,0,true,0,true,true,90,false,0,0,0,false)
            else
            end
            task._Wait(10)
        end
    end)
end
