_editor_class["sc_2_beer"]=Class(_object)
_editor_class["sc_2_beer"].init=function(self,_x,_y,angle, v)
    self.x,self.y=_x,_y
    self.img="ani:beer"
    self.layer=LAYER_PLAYER_BULLET+5
    self.group=GROUP_GHOST
    self.hide=false
    self.bound=true
    self.navi=false
    self.hp=200
    self.maxhp=200
    self.colli=true
    self._servants={}
    self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.hscale = 0.75
    self.vscale = 0.75
    self.rot = 0
    lasttask=task.New(self,function()
        do local i,_d_i,a,_d_a=(0),(255/25),(0),(v/25) for _=1,25 do
            SetV2(self,a,angle,false,false)
            _object.set_color(self,"mul+alpha",i,255,255,255)
            task._Wait(1)
        i=i+_d_i a=a+_d_a end end
        local hit_time = 0
        local cd = 0
        self.first_hit = false
        for _=1,_infinite do
            if Dist(self, player) < 32 then
                if cd == 0 then
                    SetV2(self,v,Angle(player,self),false,false)
                    self.first_hit = true
                    cd = 10
                else
                end
            else
                cd = max(0, cd - 1)
            end
            for i, o in ObjList(GROUP_ENEMY) do
               if self.first_hit and lstg.ColliCheck(self, o) then
                    o.hit = true
                    Del(self)
               end
            end
            if self.y>224 then
                PlaySound("nice",1.0,self.x/256,true)
                self.y=448-self.y
                self.vy=-self.vy
                hit_time = hit_time + 1
                self.first_hit = true
            else
            end
            if self.y<-224 then
                PlaySound("nice",1.0,self.x/256,true)
                self.y=-448-self.y
                self.vy=-self.vy
                hit_time = hit_time + 1
                self.first_hit = true
            else
            end
            if self.x>196 then
                PlaySound("nice",1.0,self.x/256,true)
                self.x=392-self.x
                self.vx=-self.vx
                hit_time = hit_time + 1
                self.first_hit = true
            else
            end
            if self.x<-196 then
                PlaySound("nice",1.0,self.x/256,true)
                self.x=-392-self.x
                self.vx=-self.vx
                hit_time = hit_time + 1
                self.first_hit = true
            else
            end
            if hit_time == 9 then
                _object.set_color(self,"mul+alpha",255,255,74,0)
            else
            end
            if hit_time == 10 then
                do local a,_d_a=(ran:Float(0,360)),(18) for _=1,20 do
                    last=New(_straight,ball_big,COLOR_ORANGE,self.x,self.y,3,a,false,0,true,true,0,false,0,0,0,false)
                a=a+_d_a end end
                PlaySound("ice",1.0,self.x/256,true)
                _del(self,true)
            else
            end
            task._Wait(1)
        end
    end)
end
