_tmp_sc=boss.card.New("旧约「以酒还酒」",2,5,90,800,{50,0,20},false)
function _tmp_sc:before()
    last=New(_editor_class["NB_Portrait_AI"],0,0,_)
    self.spellname=aic.ui.NewSpellname(self, '旧约「以酒还酒」')
end
function _tmp_sc:init()
    lasttask=task.New(self,function()
        task.MoveTo(0,120,60,MOVE_NORMAL)
        for _=1,_infinite do
            New(boss_cast_ef, self.x, self.y, 250, 245, 220, 0, 30)
            local angle_beer = Angle(self, player)
            last=New(_editor_class["sc_2_beer"],self.x,self.y,angle_beer,2)
            self.beer = last
            self.crows = {}
            self.crow_drank = nil
            do local a,_d_a=(angle_beer - 22.5),(45) for _=1,8 do
                last=New(_editor_class["sc_2_crow"],self.x,self.y,a, 200, 0.5, 1)
                _connect(self,last,0,true)
                table.insert(self.crows, last)
            a=a+_d_a end end
            do local a,_d_a=(angle_beer - 30),(60) for _=1,6 do
                last=New(_editor_class["sc_2_crow"],self.x,self.y,a, 150, -0.4, 2)
                _connect(self,last,0,true)
                table.insert(self.crows, last)
            a=a+_d_a end end
            do local a,_d_a=(angle_beer - 60),(120) for _=1,3 do
                last=New(_editor_class["sc_2_crow"],self.x,self.y,a, 100, 0.3, 1)
                _connect(self,last,0,true)
                table.insert(self.crows, last)
            a=a+_d_a end end
            for _=1,_infinite do
                if self.hit == true then
                    PlaySound("enep00",0.5,self.x/256,true)
                    self.beer = nil
                    Damage(self, 450)
                    for i, o in ipairs(self.crows) do
                        if IsValid(o) then
                           Kill(o)
                        end
                    end
                    self.hit = false
                    self.crow_drank = nil
                    do break end
                else
                end
                if not IsValid(self.beer) then
                    self.beer = nil
                    if not IsValid(self.crow_drank) then
                        for i, o in ipairs(self.crows) do
                            if IsValid(o) then
                               Kill(o)
                            end
                        end
                        self.crow_drank = nil
                        do break end
                    else
                    end
                else
                end
                task._Wait(1)
            end
        end
    end)
end
function _tmp_sc:beforedel()
end
function _tmp_sc:del()
    if IsValid(self.spellname) then
        _del(self.spellname,true)
    else
    end
    for i, o in ipairs(self.crows) do
        if IsValid(o) then
            Del(o)
        end
    end
    
    if IsValid(self.beer) then
    	Del(self.beer)
    else
    	print("no beer")
    end
    
    if IsValid(self.crow_drank) then
    	Del(self.crow_drank)
    end
    _drop_item(item_extend,1,self.x,self.y)
end
function _tmp_sc:after()
end
