stage.group.DefStageFunc('SpellCard@Hard','init',function(self)
    _init_item(self)
    difficulty=self.group.difficulty
    New(mask_fader,'open')
    if jstg then jstg.CreatePlayers() else New(_G[lstg.var.player_name]) end
    lasttask=task.New(self,function()
        New(HM_hzc4_background)
        LoadMusicRecord("bgm2")
        _play_music("bgm2")
        LoadMusicRecord("bgm4")
        _play_music("bgm4")
        last=New(_editor_class["staff"],0,0,_)
        player.lock = true
        for _=1,_infinite do
            if last.finished then break end
            task._Wait(1)
        end
        player.lock = false
        task._Wait(60)
    end)
    task.New(self,function()
        while coroutine.status(self.task[1])~='dead' do task.Wait() end
        stage.group.FinishReplay()
        New(mask_fader,'close')
        task.New(self,function()
            local _,bgm=EnumRes('bgm')
            for i=1,30 do
                for _,v in pairs(bgm) do
                    if GetMusicState(v)=='playing' then
                        SetBGMVolume(v,1-i/30)
                    end
                end
                task.Wait()
            end
        end)
        task.Wait(30)
        stage.group.FinishStage()
    end)
end)
